# -*- coding: utf-8 -*-
r"""The translation tables for every language after French.

One dict per language, keyed on the English text exactly as it is written in
the code. A key with no entry is not translated yet: the generator leaves
that row out of the language's file and tr() falls back to the English.

The keys are in the order the French file lists them, and
tools/gen_lang_tables.py writes each .cpp in the shape of lang_fr.cpp, so the
same string sits in the same place in every language's file. A language that
arrives later is a new dict, not an edit to eight hundred existing lines.

One hard rule: a translation must keep its format specifiers, in the same
order. The line goes to format(), which is plain printf - it reads its
arguments in the order the specifiers appear, so swapping "%d of %zu" round
hands an int to a %zu, and adding a second %s reads an argument nobody
passed. Japanese, Korean and Chinese would all rather put the total before
the count; that needs positional specifiers (%2$zu), which this build has not
been tested with, so the English order is kept and the wording works around
it. tools/i18n_scan.py --check refuses a mismatch.

    tools/gen_lang_tables.py        rewrite the .cpp files from these tables
    tools/i18n_scan.py --all        how far each language has got
"""

ORDER = ("de", "es", "it", "nl", "pt", "ru", "ja", "ko", "zh_hans",
         "zh_hant")

