# ---- the quest: the tower off the games shelf, fought automatically. A floor
# is a floor of a building rather than a level of a game. The four class names
# sit in an eighteen-pixel stat block, so each one is a single short noun in
# every language; the blow-by-blow lines are one line under the shadow and
# must not wrap.
